import{_ as i,o as s,c as a,ag as t}from"./chunks/framework.DQQHyi2x.js";const m=JSON.parse('{"title":"CC Bridge","description":"","frontmatter":{},"headers":[],"relativePath":"features/cc-bridge.md","filePath":"features/cc-bridge.md"}'),n={name:"features/cc-bridge.md"};function o(r,e,l,u,c,d){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="cc-bridge" tabindex="-1">CC Bridge <a class="header-anchor" href="#cc-bridge" aria-label="Permalink to &quot;CC Bridge&quot;">​</a></h1><p>Discover and monitor live Claude Code sessions running in tmux with a multi-terminal grid view.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>CC Bridge provides real-time visibility into Claude Code sessions running in tmux. You can observe up to 4 terminals simultaneously, spawn new sessions, and terminate existing ones.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="discovering-sessions" tabindex="-1">Discovering Sessions <a class="header-anchor" href="#discovering-sessions" aria-label="Permalink to &quot;Discovering Sessions&quot;">​</a></h3><p>The left sidebar automatically discovers active Claude Code tmux sessions. Sessions appear as cards with their name and status.</p><h3 id="viewing-terminals" tabindex="-1">Viewing Terminals <a class="header-anchor" href="#viewing-terminals" aria-label="Permalink to &quot;Viewing Terminals&quot;">​</a></h3><p>Click a session in the sidebar to add it to the terminal grid. The grid supports up to <strong>4 simultaneous panes</strong> in a 2x2 layout.</p><ul><li>Click a session again to remove it from the grid</li><li>Click the <strong>fullscreen</strong> icon on a pane to focus on a single session</li><li>Press <strong>Escape</strong> to exit fullscreen</li></ul><h3 id="spawning-sessions" tabindex="-1">Spawning Sessions <a class="header-anchor" href="#spawning-sessions" aria-label="Permalink to &quot;Spawning Sessions&quot;">​</a></h3><p>Click <strong>&quot;New Session&quot;</strong> to spawn a new Claude Code terminal in tmux. A dialog lets you configure the session before launching.</p><h3 id="terminating-sessions" tabindex="-1">Terminating Sessions <a class="header-anchor" href="#terminating-sessions" aria-label="Permalink to &quot;Terminating Sessions&quot;">​</a></h3><p>Use the <strong>&quot;Kill Session&quot;</strong> button to terminate a running tmux session. A confirmation dialog prevents accidental termination.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>CC Bridge uses a PTY relay to stream terminal output:</p><ol><li>Backend discovers tmux sessions via <code>tmux ls</code></li><li>Frontend requests terminal content via the API</li><li>Backend captures pane content with <code>tmux capture-pane</code></li><li>Terminal output streams to the browser in real-time</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>CC Bridge is configuration-free. It auto-discovers any active tmux sessions on the system.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>CC Bridge requires tmux to be installed and sessions to be running. If no tmux sessions exist, the sidebar will be empty.</p></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use the <strong>2x2 grid</strong> to monitor multiple sessions at once — great for parallel development.</li><li><strong>Fullscreen mode</strong> gives you a focused view of one session.</li><li>Sessions are discovered automatically — no setup needed beyond having tmux running.</li></ul>',22)])])}const g=i(n,[["render",o]]);export{m as __pageData,g as default};
